1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	import java.util.Set;
5	
6	/**
7	 * Single source of truth for what a "normalized" owner email is: lower-cased, so the
8	 * stored value is canonical regardless of the casing the client sent.
9	 * Syntactic validity is enforced upstream by the {@code @Email} constraint on the
10	 * request DTO; this step only canonicalizes an already-valid (or absent) address.
11	 * It also owns the disposable-domain blocklist (see {@link ValidateOwnerEmailDomain}).
12	 */
13	final class OwnerEmails {
14	
15	    /** Known disposable-email providers; an owner email on one of these is rejected. */
16	    private static final Set<String> DISPOSABLE_DOMAINS = Set.of(
17	            "mailinator.com", "tempmail.com", "guerrillamail.com");
18	
19	    private OwnerEmails() {
20	    }
21	
22	    static String normalize(String email) {
23	        return email == null ? null : email.toLowerCase(Locale.ROOT);
24	    }
25	
26	    /** The lower-cased domain part (after the last '@') of a normalized email, or null. */
27	    static String domainOf(String email) {
28	        String normalized = normalize(email);
29	        if (normalized == null) {
30	            return null;
31	        }
32	        int at = normalized.lastIndexOf('@');
33	        return at < 0 ? null : normalized.substring(at + 1);
34	    }
35	
36	    /** True when the email's domain is on the disposable-domain blocklist. */
37	    static boolean isDisposableDomain(String email) {
38	        String domain = domainOf(email);
39	        return domain != null && DISPOSABLE_DOMAINS.contains(domain);
40	    }
41	}
