1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	/**
4	 * Single source of truth for what a "normalized" owner telephone is: the number in
5	 * <a href="https://en.wikipedia.org/wiki/E.164">E.164</a> form. Used by
6	 * {@link NormalizeOwnerTelephone} to canonicalize an owner's telephone before it is stored,
7	 * so every owner's stored number is in one canonical form.
8	 *
9	 * <p>The rule: spaces, dashes and brackets are stripped. If a leading {@code '+'} (and
10	 * therefore an explicit country code) is present it is kept; otherwise country code
11	 * {@code '+61'} is assumed and a single leading {@code '0'} is dropped from the national
12	 * digits. The result must have 8 to 15 digits after the {@code '+'}, and for a recognized
13	 * country code the national number must have the exact length that country requires
14	 * ({@code '+61'} => 9 national digits, {@code '+1'} => 10), else it is invalid.
15	 */
16	final class OwnerTelephones {
17	
18	    private OwnerTelephones() {
19	    }
20	
21	    /**
22	     * Returns the E.164 form of {@code telephone}, or {@code null} if it cannot form a
23	     * valid E.164 number (non-digit characters remaining, not 8-15 digits after the
24	     * {@code '+'}, or a wrong national-number length for a recognized country code).
25	     */
26	    static String toE164(String telephone) {
27	        if (telephone == null) {
28	            return null;
29	        }
30	        String trimmed = telephone.trim();
31	        boolean explicitCountryCode = trimmed.startsWith("+");
32	        // Strip spaces, dashes and brackets; keep a leading '+' and the digits.
33	        String stripped = trimmed.replaceAll("[\\s()\\-]", "");
34	        String digits = explicitCountryCode ? stripped.substring(1) : stripped;
35	        if (!digits.matches("\\d+")) {
36	            return null;
37	        }
38	        if (!explicitCountryCode) {
39	            // No country code: assume +61 and drop a single leading national '0'.
40	            if (digits.startsWith("0")) {
41	                digits = digits.substring(1);
42	            }
43	            digits = "61" + digits;
44	        }
45	        if (digits.length() < 8 || digits.length() > 15) {
46	            return null;
47	        }
48	        if (!hasValidNationalLength(digits)) {
49	            return null;
50	        }
51	        return "+" + digits;
52	    }
53	
54	    /**
55	     * Checks the national-number length against the country code: {@code '+61'} requires
56	     * exactly 9 national digits and {@code '+1'} exactly 10. Unrecognized country codes are
57	     * accepted on the general 8-15 digit rule alone.
58	     */
59	    private static boolean hasValidNationalLength(String digits) {
60	        if (digits.startsWith("61")) {
61	            return digits.length() - 2 == 9;
62	        }
63	        if (digits.startsWith("1")) {
64	            return digits.length() - 1 == 10;
65	        }
66	        return true;
67	    }
68	}
