3	import org.springframework.samples.petclinic.model.Owner;
4	
5	/**
6	 * Decides which 4-digit postcode is valid for an owner's city. The acceptable range is
7	 * keyed by the city's region (via {@link Owner#regionForCity(String)}): NSW 2000-2099,
8	 * VIC 3000-3099, QLD 4000-4099. A city whose region is not in the range table (including
9	 * the {@code "UNKNOWN"} region) accepts any 4-digit postcode. Both the region ranges and
10	 * the postcode-to-region lookup live in {@link Owner} as the single source of truth; this
11	 * helper only combines them. Postcode format (exactly 4 digits) is enforced upstream by
12	 * the {@code @Pattern} constraint on the request DTO, so this helper range-checks an
13	 * already-well-formed postcode.
14	 */
15	final class OwnerPostcodes {
16	
17	    private OwnerPostcodes() {
18	    }
19	
20	    /**
21	     * Whether the (well-formed, 4-digit) postcode is valid for the given city. True when
22	     * the city's region has no known range (any 4-digit postcode is accepted), otherwise
23	     * true only when the postcode falls within that region's inclusive range — i.e. when
24	     * the postcode itself resolves to the city's region.
25	     */
26	    static boolean isValidForCity(String postcode, String city) {
27	        String region = Owner.regionForCity(city);
28	        if (!Owner.hasPostcodeRange(region)) {
29	            return true;
30	        }
31	        return region.equals(Owner.regionForPostcode(postcode));
32	    }
33	}
