package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;
import java.util.Set;

/**
 * Single source of truth for what a "normalized" owner email is: lower-cased, so the
 * stored value is canonical regardless of the casing the client sent.
 * Syntactic validity is enforced upstream by the {@code @Email} constraint on the
 * request DTO; this step only canonicalizes an already-valid (or absent) address.
 * It also owns the disposable-domain blocklist (see {@link ValidateOwnerEmailDomain}).
 */
final class OwnerEmails {

    /** Known disposable-email providers; an owner email on one of these is rejected. */
    private static final Set<String> DISPOSABLE_DOMAINS = Set.of(
            "mailinator.com", "tempmail.com", "guerrillamail.com");

    private OwnerEmails() {
    }

    static String normalize(String email) {
        return email == null ? null : email.toLowerCase(Locale.ROOT);
    }

    /** The lower-cased domain part (after the last '@') of a normalized email, or null. */
    static String domainOf(String email) {
        String normalized = normalize(email);
        if (normalized == null) {
            return null;
        }
        int at = normalized.lastIndexOf('@');
        return at < 0 ? null : normalized.substring(at + 1);
    }

    /** True when the email's domain is on the disposable-domain blocklist. */
    static boolean isDisposableDomain(String email) {
        String domain = domainOf(email);
        return domain != null && DISPOSABLE_DOMAINS.contains(domain);
    }
}
===== OwnerTelephones =====
package org.springframework.samples.petclinic.rest.function.owner;

/**
 * Single source of truth for what a "normalized" owner telephone is: the number in
 * <a href="https://en.wikipedia.org/wiki/E.164">E.164</a> form. Used by
 * {@link NormalizeOwnerTelephone} to canonicalize an owner's telephone before it is stored,
 * so every owner's stored number is in one canonical form.
 *
 * <p>The rule: spaces, dashes and brackets are stripped. If a leading {@code '+'} (and
 * therefore an explicit country code) is present it is kept; otherwise country code
 * {@code '+61'} is assumed and a single leading {@code '0'} is dropped from the national
 * digits. The result must have 8 to 15 digits after the {@code '+'}, and for a recognized
 * country code the national number must have the exact length that country requires
 * ({@code '+61'} => 9 national digits, {@code '+1'} => 10), else it is invalid.
 */
final class OwnerTelephones {

    private OwnerTelephones() {
    }

    /**
     * Returns the E.164 form of {@code telephone}, or {@code null} if it cannot form a
     * valid E.164 number (non-digit characters remaining, not 8-15 digits after the
     * {@code '+'}, or a wrong national-number length for a recognized country code).
     */
    static String toE164(String telephone) {
        if (telephone == null) {
            return null;
        }
        String trimmed = telephone.trim();
        boolean explicitCountryCode = trimmed.startsWith("+");
        // Strip spaces, dashes and brackets; keep a leading '+' and the digits.
        String stripped = trimmed.replaceAll("[\\s()\\-]", "");
        String digits = explicitCountryCode ? stripped.substring(1) : stripped;
        if (!digits.matches("\\d+")) {
            return null;
        }
        if (!explicitCountryCode) {
            // No country code: assume +61 and drop a single leading national '0'.
            if (digits.startsWith("0")) {
                digits = digits.substring(1);
            }
            digits = "61" + digits;
        }
        if (digits.length() < 8 || digits.length() > 15) {
            return null;
        }
        if (!hasValidNationalLength(digits)) {
            return null;
        }
        return "+" + digits;
    }

    /**
     * Checks the national-number length against the country code: {@code '+61'} requires
     * exactly 9 national digits and {@code '+1'} exactly 10. Unrecognized country codes are
     * accepted on the general 8-15 digit rule alone.
     */
    private static boolean hasValidNationalLength(String digits) {
        if (digits.startsWith("61")) {
            return digits.length() - 2 == 9;
        }
        if (digits.startsWith("1")) {
            return digits.length() - 1 == 10;
        }
        return true;
    }
}
===== OwnerPostcodes =====
package org.springframework.samples.petclinic.rest.function.owner;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Decides which 4-digit postcode is valid for an owner's city. The acceptable range is
 * keyed by the city's region (via {@link Owner#regionForCity(String)}): NSW 2000-2099,
 * VIC 3000-3099, QLD 4000-4099. A city whose region is not in the range table (including
 * the {@code "UNKNOWN"} region) accepts any 4-digit postcode. Both the region ranges and
 * the postcode-to-region lookup live in {@link Owner} as the single source of truth; this
 * helper only combines them. Postcode format (exactly 4 digits) is enforced upstream by
 * the {@code @Pattern} constraint on the request DTO, so this helper range-checks an
 * already-well-formed postcode.
 */
final class OwnerPostcodes {

    private OwnerPostcodes() {
    }

    /**
     * Whether the (well-formed, 4-digit) postcode is valid for the given city. True when
     * the city's region has no known range (any 4-digit postcode is accepted), otherwise
     * true only when the postcode falls within that region's inclusive range — i.e. when
     * the postcode itself resolves to the city's region.
     */
    static boolean isValidForCity(String postcode, String city) {
        String region = Owner.regionForCity(city);
        if (!Owner.hasPostcodeRange(region)) {
            return true;
        }
        return region.equals(Owner.regionForPostcode(postcode));
    }
}
