13	/**
14	 * Assigns the owner's {@code customerCode}, formatted {@code <REGION>-<HASH8>} where
15	 * REGION is the region code derived from the postcode (NSW/VIC/QLD, or {@code UNKNOWN}
16	 * when the postcode is absent or in no known range) and HASH8 is the first 8 upper-case
17	 * hex characters of the SHA-256 digest over the normalized telephone concatenated with
18	 * the last name (e.g. {@code NSW-A1B2C3D4}). Runs after the telephone has been normalized
19	 * to E.164, so the hash is stable for a given owner.
20	 *
21	 * <p>When the computed code collides with an existing owner's {@code customerCode}, it is
22	 * de-duplicated by appending {@code -<n>} with the smallest {@code n} of 2 or more that
23	 * makes it unique (e.g. {@code NSW-A1B2C3D4-2}), so distinct owners always receive
24	 * distinct customer codes.
25	 */
26	public class AssignCustomerCode {
27	
28	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
29	        String region = Owner.identityRegion(owner.getPostcode());
30	        String hash8 = sha256UpperHex8(owner.getTelephone() + owner.getLastName());
31	        String base = region + "-" + hash8;
32	
33	        Set<String> existing = new HashSet<>();
34	        for (Owner other : ownerRepository.findAll()) {
35	            if (other.getCustomerCode() != null) {
36	                existing.add(other.getCustomerCode());
37	            }
38	        }
39	
40	        String code = base;
41	        for (int n = 2; existing.contains(code); n++) {
42	            code = base + "-" + n;
43	        }
44	        owner.setCustomerCode(code);
45	    }
46	
47	    /**
48	     * The first 8 upper-case hex characters of the SHA-256 digest of the UTF-8 bytes of
49	     * {@code value}.
50	     */
51	    private static String sha256UpperHex8(String value) {
52	        byte[] digest;
53	        try {
54	            digest = MessageDigest.getInstance("SHA-256")
55	                .digest(value.getBytes(StandardCharsets.UTF_8));
56	        } catch (NoSuchAlgorithmException ex) {
57	            throw new IllegalStateException("SHA-256 is required but unavailable", ex);
58	        }
59	        StringBuilder sb = new StringBuilder(8);
60	        for (int i = 0; i < 4; i++) {
61	            sb.append(String.format("%02X", digest[i]));
62	        }
63	        return sb.toString();
64	    }
