11	/**
12	 * First step of the create pipeline. When the request carries an {@code Idempotency-Key}
13	 * that was already seen, the owner created the first time is published and the {@code replay}
14	 * branch is taken to respond 200 with it, instead of continuing on to create a duplicate. A
15	 * missing or new key takes the {@code proceed} branch and falls through to validation.
16	 *
17	 * <p>The replayed owner is published as the pipeline's {@link Owner} so the shared responder
18	 * maps and sends it, rather than duplicating that logic here.
19	 */
20	public class CheckIdempotencyKey {
21	
22	    public void service(ServerHttpConnection connection, IdempotencyStore store,
23	            OwnerRepository ownerRepository, Out<Owner> ownerOut,
24	            @Flow("replay") PipelineBranch replay, @Flow("proceed") PipelineBranch proceed) {
25	        Integer id = store.find(IdempotencyStore.keyFrom(connection));
26	        if (id != null) {
27	            try {
28	                Owner owner = ownerRepository.findById(id);
29	                if (owner != null) {
30	                    ownerOut.set(owner);
31	                    replay.take();
32	                    return;
33	                }
34	            }
35	            catch (DataAccessException ex) {
36	                // The recorded owner is gone; treat the key as new and create afresh.
37	            }
38	        }
39	        proceed.take();
40	    }
